<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Book a Ride | GoCycle</title><link rel="stylesheet" href="style.css"></head><body class="dashboard-body"><div class="app-shell"><aside class="sidebar"><a class="brand brand-link" href="dashboard.php">GO<span>CYCLE</span></a><p class="sidebar-label">MENU</p><a class="nav-link" href="dashboard.php">Dashboard</a><a class="nav-link active" href="user_rides.php">Book a Ride</a><a class="nav-link" href="user_bookings.php">My Bookings</a><a class="nav-link" href="user_account.php">My Account</a><div class="sidebar-bottom"><div class="sidebar-user"><div class="avatar"><?php echo strtoupper(substr($user['username'],0,1)); ?></div><div><strong><?php echo htmlspecialchars($user['username']); ?></strong><small>User</small></div></div><a class="nav-link logout-link" href="logout.php">→&nbsp;&nbsp; Log out</a></div></aside><main class="main-content"><header class="topbar"><div><p class="eyebrow">GOCYCLE / SCHEDULE</p><h1>Book a Ride</h1></div></header><section class="content-card"><div class="section-heading"><div><h3>Choose your schedule</h3><p>Select a date to view all ride times. Full slots remain visible but cannot be booked.</p></div></div><?php if($notice): ?><div class="booking-notice <?php echo $notice_type==='error'?'error':'success'; ?>"><?php echo htmlspecialchars($notice); ?></div><?php endif; ?><form method="get" action="user_rides.php" class="booking-date-form"><label for="ride_date">Ride date</label><div class="booking-date-controls"><input type="date" id="ride_date" name="ride_date" value="<?php echo htmlspecialchars($selected_date); ?>" min="<?php echo date('Y-m-d'); ?>" max="<?php echo date('Y-m-d',strtotime('+30 days')); ?>" required><button class="primary-action" type="submit">Check availability</button></div></form><div class="ride-slot-grid"><?php foreach($ride_slots as $slot): $taken=$slot_counts[$slot]??0; $full=$taken >= $slot_capacity; $past=$selected_date===date('Y-m-d') && $slot<=date('H:i:s'); ?><article class="ride-slot <?php echo ($full||$past)?'slot-unavailable':''; ?>"><div class="ride-slot-top"><span class="ride-time"><?php echo date('g:i A',strtotime($slot)); ?></span><span class="slot-status <?php echo ($full||$past)?'full':'available'; ?>"><?php echo $full?'FULL':($past?'PASSED':'AVAILABLE'); ?></span></div><p><?php echo $full?'No seats left':($past?'This time has passed':($slot_capacity-$taken).' seat(s) remaining'); ?></p><form method="post" action="ride_booking.php" onsubmit="return confirm('Confirm booking for <?php echo date('g:i A', strtotime($slot)); ?> on <?php echo date('F j, Y', strtotime($selected_date)); ?>?');"><input type="hidden" name="csrf" value="<?php echo htmlspecialchars(csrf_token()); ?>"><input type="hidden" name="booking_action" value="book"><input type="hidden" name="ride_date" value="<?php echo htmlspecialchars($selected_date); ?>"><input type="hidden" name="ride_time" value="<?php echo htmlspecialchars($slot); ?>"><button type="submit" class="book-slot-button" <?php echo ($full||$past)?'disabled':''; ?>><?php echo $full?'Slot Full':($past?'Unavailable':'Book this ride'); ?></button></form></article><?php endforeach; ?></div><p class="booking-footnote">Each slot has five seats. Double booking is not allowed. Schedules are available up to 30 days ahead.</p></section><footer class="page-footer">© 2026 GoCycle <span>Ride • Explore • Repeat</span></footer></main></div></body></html>
